<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {type Level,type Progress,load,persist,begin,verify,act,canClaim} from './game';
const index=ref<string[]>([]);const labels=ref<Record<string,string>>({});const level=ref<Level|null>(null);const progress=ref<Progress|null>(load());const page=ref('home');const error=ref('');const result=ref('');const operation=ref('create');const resourceId=ref('');const kind=ref('COMPARTMENT');const rawProps=ref('');const region=ref('ap-tokyo-1');const card=ref('Tenancy');const terminal=ref('');
const name=(k:string)=>labels.value[k]||k;const chapter=(path:string)=>Number(path.match(/ch(\d+)/)?.[1]||0);const currentObjectives=computed(()=>level.value&&progress.value?level.value.objectives.map(o=>({text:name(o.messageKey),status:verify(o,progress.value!.world)})):[]);
async function choose(path:string){try{const r=await fetch(import.meta.env.BASE_URL+'content/'+path);if(!r.ok)throw Error('Level load failed');level.value=await r.json() as Level;if(progress.value?.levelId!==level.value.id)progress.value=begin(level.value,progress.value);persist(progress.value);page.value='mission';error.value='';result.value=''}catch(e){error.value=String(e)}}
function execute(op:string,id:string,props:Record<string,string>={}){if(!level.value||!progress.value)return;result.value=act(progress.value,level.value,op,id,props)}
function submit(){const props:Record<string,string>={};for(const line of rawProps.value.split('\n')){if(!line.trim())continue;const i=line.indexOf('=');if(i<1){result.value='Each property must be key=value';return}props[line.slice(0,i).trim()]=line.slice(i+1).trim()}if(operation.value==='create')props.kind=kind.value;execute(operation.value,resourceId.value,props)}
function runTerminal(){if(!progress.value)return;const s=terminal.value.trim();const mapping:Record<string,string>={'oci compute instance list':'COMPUTE','oci network vcn list':'VCN','oci network subnet list':'SUBNET','oci iam compartment list':'COMPARTMENT','oci iam group list':'GROUP','oci iam policy list':'POLICY','oci os bucket list':'BUCKET','oci bv volume list':'VOLUME','oci db database list':'DATABASE'};if(s in mapping){result.value=JSON.stringify(Object.values(progress.value.world.resources).filter(r=>r.kind===mapping[s]),null,2)}else if(/^advance [1-9][0-9]*$/.test(s)){execute('advance_tick','')}else result.value='Unsupported in Web preview; original Android terminal contains more commands.'}
function finish(){if(!level.value||!progress.value)return;if(!canClaim(level.value,progress.value.world)){result.value='Required objectives or safety constraints are unverified. Full simulation engine port pending.';return}if(!progress.value.completed[level.value.id]){progress.value.completed[level.value.id]=1;progress.value.xp+=level.value.reward.xp;persist(progress.value)}result.value='Completed!'}
function reset(){if(level.value){progress.value=begin(level.value,progress.value);persist(progress.value);result.value='Reset'}}
onMounted(async()=>{try{const [a,b]=await Promise.all([fetch(import.meta.env.BASE_URL+'content/index.json'),fetch(import.meta.env.BASE_URL+'content/locales/zh-CN.json')]);if(!a.ok||!b.ok)throw Error('Missing original OCI content');index.value=await a.json();labels.value=await b.json();const found=index.value.find(x=>x.includes(progress.value?.levelId.replace('oci-','level-')+'.json'));if(found)await choose(found)}catch(e){error.value=String(e)}});
</script>
<template><div class="app"><header><strong>☁ OCI CLOUD COMMANDER</strong><span>ASTRA CLOUD OPERATIONS · TOKYO</span><span>⭐ {{Object.keys(progress?.completed||{}).length}} / {{index.length}} · XP {{progress?.xp||0}}</span></header><nav><button v-for="p in ['home','map','mission','console','topology','terminal','learning']" :key="p" @click="page=p">{{({home:'指挥中心',map:'章节地图',mission:'任务',console:'OCI Console',topology:'资源图',terminal:'Terminal',learning:'学习'} as Record<string,string>)[p]}}</button></nav><p class="notice">独立离线教学模拟器 · 不连接真实 Oracle Cloud · Web 预览版尚未完整移植 Android 规则引擎</p><p v-if="error" class="error">{{error}}</p><section v-if="page==='home'"><h1>OCI 云端守护者</h1><p>2030 年，你加入 Astra Cloud Operations。调查云端故障、学习 OCI 资源和网络。</p><button class="primary" @click="page='map'">开始任务</button></section><section v-else-if="page==='map'"><h2>五个章节 · {{index.length}} 关</h2><div v-for="c in [1,2,3,4,5]" :key="c"><h3>Chapter {{c}}</h3><div class="grid"><button v-for="path in index.filter(p=>chapter(p)===c)" :key="path" @click="choose(path)" :disabled="index.indexOf(path)>0 && !progress?.completed['oci-'+index.indexOf(path).toString().padStart(3,'0')]">{{path.match(/level-(\d+)/)?.[1]}} · {{name('levels.'+(path.match(/level-(\d+)/)?.[1]||'')+'.title')}}</button></div></div></section><section v-else-if="page==='mission'"><template v-if="level&&progress"><h2>{{name(level.titleKey)}}</h2><p>{{name(level.scenario.briefKey)}}</p><h3>任务目标</h3><div v-for="(o,i) in currentObjectives" :key="i" class="objective">{{o.status===true?'✅':o.status===false?'⬜':'❔'}} {{o.text}}</div><p>❔ 表示 Web 版尚未实现该目标的完整规则判定。</p><h3>步骤</h3><div v-for="s in level.steps" :key="s.id"><p>{{name(s.textKey)}}</p><details><summary>提示</summary><p v-for="h in s.hintKeys" :key="h">{{name(h)}}</p></details></div><h3>学习卡</h3><div class="controls"><select v-model="card"><option v-for="c in ['Tenancy','Region','AD','FD']" :key="c">{{c}}</option></select><button @click="execute('study_card',card)">学习概念</button><select v-model="region"><option>ap-tokyo-1</option><option>ap-osaka-1</option><option>us-ashburn-1</option></select><button @click="execute('select_region',region)">选择 Region</button><button @click="execute('inspect','root')">检查世界状态</button></div><div class="controls"><button class="primary" @click="finish">检查 / 领取奖励</button><button @click="reset">重置本关</button></div></template><p v-else>请在章节地图中选择关卡。</p></section><section v-else-if="page==='console'"><h2>OCI Console</h2><p>Region: {{progress?.world.region||'not selected'}}</p><div class="controls"><select v-model="operation"><option v-for="op in ['create','update','delete','inspect','advance_tick']" :key="op">{{op}}</option></select><input v-model="resourceId" placeholder="Resource ID"><select v-model="kind"><option v-for="k in ['COMPARTMENT','GROUP','POLICY','VCN','SUBNET','COMPUTE','BUCKET','VOLUME','LOAD_BALANCER']" :key="k">{{k}}</option></select></div><textarea v-model="rawProps" placeholder="key=value&#10;another=value"></textarea><button class="primary" @click="submit">执行模拟操作</button><h3>Resources</h3><div class="grid"><div class="node" v-for="r in Object.values(progress?.world.resources||{})" :key="r.id"><b>{{r.id}}</b><small>{{r.kind}} · {{r.compartment}}</small><pre>{{JSON.stringify(r.properties,null,2)}}</pre></div></div></section><section v-else-if="page==='topology'"><h2>资源图</h2><div class="grid"><div class="node" v-for="r in Object.values(progress?.world.resources||{})" :key="r.id">☁ {{r.id}} · {{r.kind}}</div></div><p>拖动、资源依赖和网络拓扑计算尚未移植。</p></section><section v-else-if="page==='terminal'"><h2>教学 Terminal</h2><p>例如：oci compute instance list / oci network vcn list</p><form @submit.prevent="runTerminal"><input v-model="terminal" placeholder="oci compute instance list"><button class="primary">运行</button></form></section><section v-else><h2>知识库</h2><p>Tenancy、Region、Availability Domain、Fault Domain。</p><p>完整教学内容请在 Mission 关卡中阅读。</p></section><pre v-if="result" class="result">{{result}}</pre><footer>Unofficial OCI educational simulator · No real credentials or charges.</footer></div></template>